// The object library of Aurora XR scenes: each TYPE is a thing the Aurora knows (name, size in the
// miniature, where it goes, the themes it belongs to, how it moves, a description written for her,
// what it goes with) and has one or more 3D VARIANTS (so ten houses are not the same house).
// Sources, all CC0 (public domain): Kenney (kenney.nl) packs, Quaternius models (quaternius.com, via
// poly.pizza), and "proc:" for the few drawn by the app itself (app/xr/xr/models.js).
// scripts/xr-assets/build.mjs turns this into app/xr/assets/catalog.json and the optimized models.
//
// Fields: tam = largest side in metres in the miniature (a 0.9 x 0.6 m plate; a person is 3 cm);
// onde = chao | agua | ar | estrada | trilho | parede (where it is put); anda = parado | passear |
// rodar | voar | nadar | flutuar | girar | orbitar | pular; zona = the kind of zone it is laid out in
// when nobody says (see app/xr/lib/compose.js); tags = themes; com = types it goes with.

const k = (pack, ...files) => files.map((f) => `k:${pack}/${f}`);
const ks = (pack, prefix, from, to) => { const out = []; for (let c = from.charCodeAt(0); c <= to.charCodeAt(0); c++) out.push(`k:${pack}/${prefix}${String.fromCharCode(c)}`); return out; };
const p = (...names) => names.map((n) => `p:${n}`);

export const TYPES = [];
const T = (id, nome, tam, onde, zona, tags, anda, desc, com, sin, v, extra = {}) => TYPES.push({ id, nome, tam, onde, zona, tags, anda, desc, com, sin, v, ...extra });

